import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import {
  HomeIcon,
  GlobeAltIcon,
  DocumentTextIcon,
  ExclamationTriangleIcon,
  CogIcon,
  AcademicCapIcon,
  Bars3Icon,
  XMarkIcon
} from '@heroicons/react/24/outline';
import { Disclosure } from '@headlessui/react';

const Navigation = () => {
  const location = useLocation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const navigation = [
    { name: 'Dashboard', href: '/', icon: HomeIcon },
    { name: 'Dominios', href: '/domains', icon: GlobeAltIcon },
    { name: 'Reportes DMARC', href: '/reports', icon: DocumentTextIcon },
    { name: 'Alertas', href: '/alerts', icon: ExclamationTriangleIcon },
    { name: 'Configuración', href: '/settings', icon: CogIcon },
    { name: 'Asistente', href: '/wizard', icon: AcademicCapIcon },
  ];

  const isActive = (href) => {
    if (href === '/') {
      return location.pathname === '/';
    }
    return location.pathname.startsWith(href);
  };

  const NavLink = ({ item, mobile = false }) => {
    const active = isActive(item.href);
    const baseClasses = mobile
      ? 'block px-3 py-2 text-base font-medium rounded-md'
      : 'inline-flex items-center px-1 pt-1 text-sm font-medium border-b-2';

    const activeClasses = mobile
      ? 'bg-primary-100 text-primary-700'
      : 'border-primary-500 text-gray-900';

    const inactiveClasses = mobile
      ? 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
      : 'border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700';

    return (
      <Link
        to={item.href}
        className={`${baseClasses} ${active ? activeClasses : inactiveClasses}`}
        onClick={() => mobile && setMobileMenuOpen(false)}
      >
        {mobile && (
          <item.icon className="mr-3 h-5 w-5" aria-hidden="true" />
        )}
        {item.name}
      </Link>
    );
  };

  return (
    <Disclosure as="nav" className="bg-white shadow">
      {({ open }) => (
        <>
          <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
            <div className="flex h-16 justify-between">
              <div className="flex">
                <div className="flex flex-shrink-0 items-center">
                  <Link to="/" className="flex items-center">
                    <div className="h-8 w-8 bg-primary-600 rounded-lg flex items-center justify-center">
                      <span className="text-white font-bold text-lg">D</span>
                    </div>
                    <span className="ml-2 text-xl font-bold text-gray-900">
                      DMARC Panel
                    </span>
                  </Link>
                </div>
                <div className="hidden sm:ml-6 sm:flex sm:space-x-8">
                  {navigation.map((item) => (
                    <NavLink key={item.name} item={item} />
                  ))}
                </div>
              </div>

              {/* Mobile menu button */}
              <div className="-mr-2 flex items-center sm:hidden">
                <Disclosure.Button className="inline-flex items-center justify-center rounded-md p-2 text-gray-400 hover:bg-gray-100 hover:text-gray-500 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-primary-500">
                  <span className="sr-only">Abrir menú principal</span>
                  {open ? (
                    <XMarkIcon className="block h-6 w-6" aria-hidden="true" />
                  ) : (
                    <Bars3Icon className="block h-6 w-6" aria-hidden="true" />
                  )}
                </Disclosure.Button>
              </div>
            </div>
          </div>

          {/* Mobile menu */}
          <Disclosure.Panel className="sm:hidden">
            <div className="space-y-1 pb-3 pt-2">
              {navigation.map((item) => (
                <NavLink key={item.name} item={item} mobile />
              ))}
            </div>
          </Disclosure.Panel>
        </>
      )}
    </Disclosure>
  );
};

export default Navigation;
